#![no_std]
use soroban_sdk::{
    contract, contracterror, contractimpl, contracttype, panic_with_error, token, Address, Env,
};

// Ledger counts: about 17,280 ledgers per day at 5 seconds each.
const DAY_IN_LEDGERS: u32 = 17_280;
const LIFETIME_THRESHOLD: u32 = 14 * DAY_IN_LEDGERS;
const LIFETIME_BUMP: u32 = 30 * DAY_IN_LEDGERS;

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    InvalidAmount = 1,
    InsufficientStake = 2,
}

#[contracttype]
pub enum DataKey {
    Token,
    Total,
    Staked(Address),
}

#[contract]
pub struct Staking;

#[contractimpl]
impl Staking {
    /// Runs once at deploy time. `token` is the Stellar Asset Contract address of the staked asset
    /// (XLM: `asset:native` in constructor.json).
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        env.storage().instance().set(&DataKey::Total, &0_i128);
    }

    /// Moves `amount` of the staked token from `user` into this contract.
    pub fn stake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        token::TokenClient::new(&env, &Self::token(&env)).transfer(
            &user,
            &env.current_contract_address(),
            &amount,
        );

        let key = DataKey::Staked(user.clone());
        let current: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        env.storage().persistent().set(&key, &(current + amount));
        env.storage()
            .persistent()
            .extend_ttl(&key, LIFETIME_THRESHOLD, LIFETIME_BUMP);

        Self::set_total(&env, Self::total_staked(env.clone()) + amount);
    }

    /// Returns `amount` of the staked token from this contract to `user`.
    /// Fails if `user` has less than `amount` staked.
    pub fn unstake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        let key = DataKey::Staked(user.clone());
        let current: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        if current < amount {
            panic_with_error!(&env, Error::InsufficientStake);
        }

        if current == amount {
            env.storage().persistent().remove(&key);
        } else {
            env.storage().persistent().set(&key, &(current - amount));
            env.storage()
                .persistent()
                .extend_ttl(&key, LIFETIME_THRESHOLD, LIFETIME_BUMP);
        }

        Self::set_total(&env, Self::total_staked(env.clone()) - amount);

        token::TokenClient::new(&env, &Self::token(&env)).transfer(
            &env.current_contract_address(),
            &user,
            &amount,
        );
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        env.storage()
            .persistent()
            .get(&DataKey::Staked(user))
            .unwrap_or(0)
    }

    /// The amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        env.storage().instance().get(&DataKey::Total).unwrap_or(0)
    }

    /// The Stellar Asset Contract address this contract stakes.
    pub fn token(env: Env) -> Address {
        env.storage().instance().get(&DataKey::Token).unwrap()
    }

    fn set_total(env: &Env, total: i128) {
        env.storage().instance().set(&DataKey::Total, &total);
    }
}

mod test;
EOF
