#![cfg(test)]

use super::*;
use soroban_sdk::{testutils::Address as _, token::StellarAssetClient, Address, Env};

struct Setup<'a> {
    env: Env,
    staking: StakingClient<'a>,
    token: token::TokenClient<'a>,
    token_admin: StellarAssetClient<'a>,
}

/// A fresh staking contract over a test Stellar Asset Contract, as the deploy does on testnet.
fn setup() -> Setup<'static> {
    let env = Env::default();
    env.mock_all_auths();

    let admin = Address::generate(&env);
    let sac = env.register_stellar_asset_contract_v2(admin);
    let token_id = sac.address();

    let contract_id = env.register(Staking, (token_id.clone(),));
    let staking = StakingClient::new(&env, &contract_id);
    let token = token::TokenClient::new(&env, &token_id);
    let token_admin = StellarAssetClient::new(&env, &token_id);

    Setup {
        env,
        staking,
        token,
        token_admin,
    }
}

#[test]
fn stake_moves_tokens_and_records_stake() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);

    s.staking.stake(&user, &400);

    assert_eq!(s.staked(&user), 400);
    assert_eq!(s.staking.staked(&user), 400);
    assert_eq!(s.staking.total_staked(), 400);
    assert_eq!(s.token.balance(&user), 600);
    assert_eq!(s.token.balance(&s.staking.address), 400);
}

#[test]
fn stake_accumulates_per_user_and_in_total() {
    let s = setup();
    let alice = Address::generate(&s.env);
    let bob = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);
    s.token_admin.mint(&bob, &1_000);

    s.staking.stake(&alice, &300);
    s.staking.stake(&alice, &200);
    s.staking.stake(&bob, &50);

    assert_eq!(s.staking.staked(&alice), 500);
    assert_eq!(s.staking.staked(&bob), 50);
    assert_eq!(s.staking.total_staked(), 550);
}

#[test]
fn unstake_returns_tokens_and_reduces_stake() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);
    s.staking.stake(&user, &500);

    s.staking.unstake(&user, &200);

    assert_eq!(s.staking.staked(&user), 300);
    assert_eq!(s.staking.total_staked(), 300);
    assert_eq!(s.token.balance(&user), 700);
    assert_eq!(s.token.balance(&s.staking.address), 300);
}

#[test]
fn unstake_everything_leaves_nothing_staked() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);
    s.staking.stake(&user, &1_000);

    s.staking.unstake(&user, &1_000);

    assert_eq!(s.staking.staked(&user), 0);
    assert_eq!(s.staking.total_staked(), 0);
    assert_eq!(s.token.balance(&user), 1_000);
}

#[test]
fn unstake_more_than_staked_fails() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);
    s.staking.stake(&user, &100);

    let result = s.staking.try_unstake(&user, &101);

    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
    assert_eq!(s.staking.staked(&user), 100);
    assert_eq!(s.staking.total_staked(), 100);
    assert_eq!(s.token.balance(&user), 900);
}

#[test]
fn unstake_without_any_stake_fails() {
    let s = setup();
    let user = Address::generate(&s.env);

    let result = s.staking.try_unstake(&user, &1);

    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
}

#[test]
fn non_positive_amounts_are_rejected() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);

    assert_eq!(s.staking.try_stake(&user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.staking.try_stake(&user, &-5), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.staking.try_unstake(&user, &0), Err(Ok(Error::InvalidAmount)));
}

#[test]
fn token_is_set_at_deploy() {
    let s = setup();
    assert_eq!(s.staking.token(), s.token.address);
    assert_eq!(s.staking.total_staked(), 0);
}

#[test]
#[should_panic]
fn stake_requires_user_authorization() {
    let env = Env::default();
    let admin = Address::generate(&env);
    let token_id = env.register_stellar_asset_contract_v2(admin).address();
    let contract_id = env.register(Staking, (token_id,));
    let staking = StakingClient::new(&env, &contract_id);
    let user = Address::generate(&env);

    // No mocked auths: the user never authorized this call.
    staking.stake(&user, &10);
}
