import { connection } from "next/server";
import { Suspense } from "react";
import { staking } from "@/lib/contracts";
import { stellar } from "@/lib/stellar";

type SearchParams = Promise<{ [key: string]: string | string[] | undefined }>;

async function readTotal(): Promise<{ total: string } | { error: string }> {
  try {
    const { result } = await staking().total_staked();
    return { total: result.toString() };
  } catch (error) {
    return { error: describe(error) };
  }
}

async function readStaked(address: string): Promise<{ staked: string } | { error: string }> {
  try {
    const { result } = await staking().staked({ user: address });
    return { staked: result.toString() };
  } catch (error) {
    return { error: describe(error) };
  }
}

// Some network errors arrive with an empty message; fall back to their text, and say where we called.
function describe(error: unknown): string {
  const reason = (error instanceof Error && error.message) || String(error) || "unknown error";
  return `${reason} (RPC: ${stellar.rpcUrl ?? "not set"})`;
}

async function TotalStaked() {
  // Call the contract when a request arrives, not while `next build` prerenders the page.
  await connection();
  const outcome = await readTotal();
  if ("error" in outcome) {
    return <p data-testid="total-error">Could not read total staked: {outcome.error}</p>;
  }
  return (
    <p>
      Total staked: <span data-testid="total-staked">{outcome.total}</span>
    </p>
  );
}

async function AccountStaked({ searchParams }: { searchParams: SearchParams }) {
  const { address: raw } = await searchParams;
  const address = (Array.isArray(raw) ? raw[0] : raw)?.trim();
  if (!address) {
    return <p>Add <code>?address=G…</code> to the URL to see an account&apos;s stake.</p>;
  }
  const outcome = await readStaked(address);
  if ("error" in outcome) {
    return <p data-testid="staked-error">Could not read the stake of {address}: {outcome.error}</p>;
  }
  return (
    <p>
      Staked by <code>{address}</code>:{" "}
      <span data-testid="staked-amount">{outcome.staked}</span>
    </p>
  );
}

export default function StakingPage({ searchParams }: { searchParams: SearchParams }) {
  return (
    <main>
      <h1>Staking</h1>
      <p>
        Network: <code>{stellar.network}</code>
      </p>
      <Suspense fallback={<p>Reading total staked…</p>}>
        <TotalStaked />
      </Suspense>
      <Suspense fallback={<p>Reading account stake…</p>}>
        <AccountStaked searchParams={searchParams} />
      </Suspense>
    </main>
  );
}
EOF
